  "takes": [
    {
      "at_ms": 0,
      "subject": "Game balance",
      "take": "The match feels like a 70‑30 tilt toward Spirit, though the streamer still sees a 30% chance for the PV side."
    },
    {
      "at_ms": 30000,
      "subject": "Ammar's hero preference",
      "take": "Ammar would rather face Ursa than Anti‑Mage, influencing the ban and pick choices."
    },
    {
      "at_ms": 60000,
      "subject": "Ursa vs Anti‑Mage difficulty",
      "take": "Ursa is considered an easier matchup for the team than Anti‑Mage, and the streamer would favor picking Axe in that scenario."
    },
    {
      "at_ms": 90000,
      "subject": "BKB effectiveness",
      "take": "A BKB on the enemy limits options, but extra space and time can still be gained."
    },
    {
      "at_ms": 120000,
      "subject": "Ursa win rate",
      "take": "Ursa has one of the highest win rates against Anti‑Mage, justifying Pobby's pick."
    },
    {
      "at_ms": 150000,
      "subject": "Lycan scaling",
      "take": "Lycan does not scale well into a Giga‑farm hero despite heavy farming."
    }
  ]
}

